from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parent
assets=json.loads((ROOT/'manifest.json').read_text())['assets']
cards=[]
for a in assets:
    svg=(ROOT/a['svg']).read_text()
    cards.append('<article data-area="'+html.escape(a['branch'])+'"><div class="art">'+svg+'</div><div class="meta"><span>'+html.escape(a['batch_no'])+'</span><span>'+html.escape(a['branch'])+'</span></div><h3>'+html.escape(a['name'])+'</h3><small>'+html.escape(a['id'])+'</small><p>'+html.escape(a['game_object'])+'</p><label><input type="checkbox" data-id="'+html.escape(a['id'])+'"> Для художественной приёмки</label></article>')
page='''<!doctype html><html lang="ru"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>DL WORLD GRAPHICS · Batch 01</title><style>
:root{font-family:system-ui,-apple-system,sans-serif;color:#283633;background:#f4f5f1}body{margin:0}header{padding:24px clamp(16px,5vw,70px);background:#e5e9dc;border-bottom:1px solid #d0d8cb}h1{font-weight:800;letter-spacing:-.03em;margin:0 0 8px;font-size:clamp(24px,3vw,38px)}header p{max-width:920px;line-height:1.55}nav{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-top:22px}button,select,input[type=search]{font:inherit;border:1px solid #b7c4b4;background:white;border-radius:9px;padding:9px 12px;min-height:38px}button{cursor:pointer;background:#536b50;color:white;border-color:#536b50}main{padding:26px clamp(12px,4vw,60px)}#count{font-size:13px;color:#59665d}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px}article{border:1px solid #d9ddcf;background:white;border-radius:15px;padding:12px;overflow:hidden}article[hidden]{display:none}.art{aspect-ratio:1;border-radius:8px;background:radial-gradient(circle,#f1f3ed,#e9ede2);display:grid;place-items:center}.art svg{width:100%;height:100%}h3{font-size:15px;margin:11px 0 7px;min-height:36px}.meta{display:flex;justify-content:space-between;gap:4px;font-weight:700;font-size:10px;color:#5b7060;padding-top:10px}.meta span:last-child{color:#798276}small{font-size:12px;color:#748276}article p{font-size:11px;color:#80877e;min-height:27px}label{display:flex;align-items:center;gap:7px;font-size:11px;color:#536955;margin-bottom:4px}#notice{padding:12px 18px;font-size:12px;color:#71695a}a{color:#486b53}
</style></head><body><header><h1>DEMENTOR LIVE — WORLD GRAPHICS</h1><p>Batch 01 · 35 отдельных SVG-объектов ISO30. Прозрачный фон, Paper Cut, исходники без растровых вырезок. <strong>Кандидаты на утверждение, не замена существующим объектам и не работающая сборка игры.</strong> Ветви WORLD-01, WORLD-02, CAVE и OBITEL пока экспериментальные.</p><nav><input id="q" type="search" placeholder="Поиск по имени и ID"/><select id="area"><option value="">Все области</option><option>RC4</option><option>GRID-02</option><option>WORLD-01</option><option>WORLD-02</option><option>CAVE-P0</option><option>OBITEL-P0</option></select><button id="export">Экспорт списка отмеченных</button><span id="count"></span></nav></header><main><div class="grid">'''+''.join(cards)+'''</div><div id="notice">Галочки предназначены для локальной ручной оценки. Они не изменяют репозиторий или готовность игрового спрайта. Сохраните результаты через «Экспорт».</div></main><script>
let items=[...document.querySelectorAll('article')];function refresh(){let q=document.querySelector('#q').value.toLowerCase(),a=document.querySelector('#area').value,n=0;for(let e of items){e.hidden=!!((a&&e.dataset.area!==a)||(q&&!e.textContent.toLowerCase().includes(q)));if(!e.hidden)n++;}document.querySelector('#count').textContent=n+' из '+items.length;}document.querySelector('#q').addEventListener('input',refresh);document.querySelector('#area').addEventListener('change',refresh);refresh();document.querySelector('#export').onclick=()=>{let ids=[...document.querySelectorAll('input[type=checkbox]:checked')].map(x=>x.dataset.id);let blob=new Blob([JSON.stringify({version:'DL-WORLD-ART-01',marked_for_review:ids,approval:'NOT_GRANTED',time:new Date().toISOString()},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='world-assets-review-checklist.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
</script></body></html>'''
(ROOT/'GALLERY.html').write_text(page)
print('HTML gallery',len(page),'bytes')
